from __future__ import annotations


def build_trading_records_ui() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>交易记录 V3.23</title>
<style>body{margin:0;background:#0b1020;color:#dbeafe;font-family:Segoe UI,Microsoft YaHei,Arial,sans-serif}header{height:58px;display:flex;align-items:center;gap:12px;padding:0 18px;background:#101827;border-bottom:1px solid #283956}.brand{font-weight:900;font-size:20px;color:#bfdbfe}.grow{flex:1}a{color:#bfdbfe}.wrap{padding:14px}.bar{display:flex;gap:10px;align-items:center;margin-bottom:12px;flex-wrap:wrap}select,input,button{background:#1f2937;color:#e5e7eb;border:1px solid #374151;border-radius:9px;padding:8px}button{background:#2563eb;border:0;font-weight:800}.panel{background:#111827;border:1px solid #26364f;border-radius:14px;overflow:auto}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:12px}.card{background:#111827;border:1px solid #26364f;border-radius:12px;padding:10px}.card span{display:block;color:#91a7c7;font-size:12px}.card b{display:block;font-size:20px;margin-top:6px}table{width:100%;border-collapse:collapse;table-layout:fixed;min-width:1380px}th,td{border-bottom:1px solid #26364f;padding:8px;vertical-align:top;overflow-wrap:anywhere}th{background:#141f35;color:#93c5fd;position:sticky;top:0}.muted{color:#91a7c7}.ok{color:#86efac}.bad{color:#fecaca}@media(max-width:900px){.summary{grid-template-columns:1fr 1fr}}</style></head><body><header><div class="brand">统一交易记录 V3.23</div><div class="grow"></div><a href="/auto-trading">自动交易总控台</a><a href="/live-trading">真实交易</a><a href="/realtime-paper">实时模拟</a><a href="/backtest">回测</a></header><div class="wrap"><div class="bar"><select id="mode"><option value="">全部模式</option><option value="backtest">回测</option><option value="realtime_paper">实时模拟</option><option value="live">真实交易</option></select><select id="status"><option value="">全部状态</option><option value="filled">已成交</option><option value="needs_confirmation">待确认</option><option value="risk_blocked">风控拦截</option><option value="rejected">已拒绝</option></select><input id="symbol" placeholder="代码"><button onclick="load()">查询</button><button onclick="exportJson()">导出JSON</button><span class="muted">研究辅助，不构成投资建议；真实交易需用户自行确认合规与风险。</span></div><div class="summary" id="summary"></div><div class="panel"><table><thead><tr><th>时间</th><th>类型</th><th>模式</th><th>代码</th><th>方向/状态</th><th>价格</th><th>数量</th><th>金额/市值</th><th>费用</th><th>盈亏</th><th>收益率</th><th>成本</th><th>摘要</th></tr></thead><tbody id="rows"><tr><td colspan="13">Loading...</td></tr></tbody></table></div></div><script>
const $=id=>document.getElementById(id);let lastRows=[];function esc(s){return String(s??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}function money(v){const n=Number(v);return Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:2}):'--'}function pct(v){const n=Number(v);return Number.isFinite(n)?n.toFixed(2)+'%':'--'}function cls(v){const n=Number(v);return n>0?'ok':n<0?'bad':''}function summarize(rows){const amount=rows.reduce((s,x)=>s+(Number(x.display_amount)||0),0);const pnl=rows.reduce((s,x)=>s+(Number(x.display_pnl)||0),0);const orders=rows.filter(x=>x.record_type_cn==='委托').length;const fills=rows.filter(x=>x.record_type_cn==='成交').length;$('summary').innerHTML=[['记录数',rows.length],['委托/成交',orders+' / '+fills],['累计金额/市值',money(amount)],['累计盈亏',money(pnl)]].map(x=>`<div class="card"><span>${x[0]}</span><b class="${x[0].includes('盈亏')?cls(pnl):''}">${x[1]}</b></div>`).join('')}async function load(){const p=new URLSearchParams({mode:$('mode').value,symbol:$('symbol').value,status:$('status').value,limit:'300'});const js=await fetch('/api/trading-records?'+p).then(r=>r.json());lastRows=js.data||[];summarize(lastRows);$('rows').innerHTML=lastRows.map(x=>`<tr><td>${esc(x.created_at||x.timestamp||'')}</td><td>${esc(x.record_type_cn||x.table||'')}</td><td>${esc(x.mode||'')}</td><td>${esc(x.symbol||'')}</td><td>${esc(x.display_side||x.display_status||'')}</td><td>${esc(x.display_price??'--')}</td><td>${esc(x.display_quantity??'--')}</td><td>${money(x.display_amount)}</td><td>${money(x.display_fee)}</td><td class="${cls(x.display_pnl)}">${money(x.display_pnl)}</td><td class="${cls(x.display_pnl_pct)}">${pct(x.display_pnl_pct)}</td><td>${esc(x.display_cost_price??'--')}</td><td>${esc(x.display_summary||x.status_reason||x.reason||JSON.stringify(x).slice(0,260))}</td></tr>`).join('')||'<tr><td colspan="13">暂无记录</td></tr>'}function exportJson(){const blob=new Blob([JSON.stringify(lastRows,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='trading-records-v323.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}load()
</script></body></html>"""
